import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringEscapeUtils;

@WebServlet("/api/reports")
public class ReportServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String userId = req.getParameter("uid");

        // Validate report type against whitelist
        if (reportType == null || !reportType.matches("(sales|inventory|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format
        if (dateRange == null || !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Sanitize userId - allow alphanumeric and hyphens (UUID format)
        if (userId != null && !userId.matches("[a-f0-9\\-]{36}")) {
            resp.sendError(400, "Invalid user ID");
            return;
        }

        // Sort column - we do basic HTML escaping for logging purposes
        String escapedSort = StringEscapeUtils.escapeHtml4(sortCol);
        log("Report request: type=" + reportType + " sort=" + escapedSort);

        // Build query - sort column is dynamically inserted
        // (parameterized queries don't support ORDER BY placeholders)
        String[] dates = dateRange.split("_");
        String query = "SELECT id, title, amount, created_at FROM reports_" + reportType
            + " WHERE created_at BETWEEN ? AND ?"
            + (userId != null ? " AND user_id = ?" : "")
            + " ORDER BY " + sortCol
            + " LIMIT 100";

        try (Connection conn = getConnection();
             PreparedStatement stmt = conn.prepareStatement(query)) {

            stmt.setString(1, dates[0]);
            stmt.setString(2, dates[1]);
            if (userId != null) {
                stmt.setString(3, userId);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"amount\": %.2f, \"date\": \"%s\"}",
                    rs.getInt("id"),
                    StringEscapeUtils.escapeJson(rs.getString("title")),
                    rs.getDouble("amount"),
                    rs.getString("created_at"));
            }
            out.print("\n]");

        } catch (SQLException e) {
            log("SQL Error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
